77	
78	void Lattice::adjust_indices()
79	{
80	  // Adjust the indices for the universes array.
81	  for (LatticeIter it = begin(); it != end(); ++it) {
82	    int uid = *it;
83	    auto search = model::universe_map.find(uid);
84	    if (search != model::universe_map.end()) {
85	      *it = search->second;
86	    } else {
87	      fatal_error(fmt::format(
88	        "Invalid universe number {} specified on lattice {}", uid, id_));
89	    }
90	  }
91	
92	  // Adjust the index for the outer universe.
93	  if (outer_ != NO_OUTER_UNIVERSE) {
94	    auto search = model::universe_map.find(outer_);
95	    if (search != model::universe_map.end()) {
96	      outer_ = search->second;
97	    } else {
98	      fatal_error(fmt::format(
99	        "Invalid universe number {} specified on lattice {}", outer_, id_));
100	    }
101	  }
102	}
