162	RectLattice::RectLattice(pugi::xml_node lat_node) : Lattice {lat_node}
163	{
164	  type_ = LatticeType::rect;
165	
166	  // Read the number of lattice cells in each dimension.
167	  std::string dimension_str {get_node_value(lat_node, "dimension")};
168	  vector<std::string> dimension_words {split(dimension_str)};
169	  if (dimension_words.size() == 2) {
170	    n_cells_[0] = std::stoi(dimension_words[0]);
171	    n_cells_[1] = std::stoi(dimension_words[1]);
172	    n_cells_[2] = 1;
173	    is_3d_ = false;
174	  } else if (dimension_words.size() == 3) {
175	    n_cells_[0] = std::stoi(dimension_words[0]);
176	    n_cells_[1] = std::stoi(dimension_words[1]);
177	    n_cells_[2] = std::stoi(dimension_words[2]);
178	    is_3d_ = true;
179	  } else {
180	    fatal_error("Rectangular lattice must be two or three dimensions.");
181	  }
182	
183	  // Read the lattice lower-left location.
184	  std::string ll_str {get_node_value(lat_node, "lower_left")};
185	  vector<std::string> ll_words {split(ll_str)};
186	  if (ll_words.size() != dimension_words.size()) {
187	    fatal_error("Number of entries on <lower_left> must be the same as the "
188	                "number of entries on <dimension>.");
189	  }
190	  lower_left_[0] = stod(ll_words[0]);
191	  lower_left_[1] = stod(ll_words[1]);
192	  if (is_3d_) {
193	    lower_left_[2] = stod(ll_words[2]);
194	  }
195	
196	  // Read the lattice pitches.
197	  std::string pitch_str {get_node_value(lat_node, "pitch")};
198	  vector<std::string> pitch_words {split(pitch_str)};
199	  if (pitch_words.size() != dimension_words.size()) {
200	    fatal_error("Number of entries on <pitch> must be the same as the "
201	                "number of entries on <dimension>.");
202	  }
203	  pitch_[0] = stod(pitch_words[0]);
204	  pitch_[1] = stod(pitch_words[1]);
205	  if (is_3d_) {
206	    pitch_[2] = stod(pitch_words[2]);
207	  }
208	
209	  // Read the universes and make sure the correct number was specified.
210	  std::string univ_str {get_node_value(lat_node, "universes")};
211	  vector<std::string> univ_words {split(univ_str)};
212	  if (univ_words.size() != n_cells_[0] * n_cells_[1] * n_cells_[2]) {
213	    fatal_error(fmt::format(
214	      "Expected {} universes for a rectangular lattice of size {}x{}x{} but {} "
215	      "were specified.",
216	      n_cells_[0] * n_cells_[1] * n_cells_[2], n_cells_[0], n_cells_[1],
217	      n_cells_[2], univ_words.size()));
218	  }
219	
220	  // Parse the universes.
221	  universes_.resize(n_cells_[0] * n_cells_[1] * n_cells_[2], C_NONE);
222	  for (int iz = 0; iz < n_cells_[2]; iz++) {
223	    for (int iy = n_cells_[1] - 1; iy > -1; iy--) {
224	      for (int ix = 0; ix < n_cells_[0]; ix++) {
225	        int indx1 = n_cells_[0] * n_cells_[1] * iz +
226	                    n_cells_[0] * (n_cells_[1] - iy - 1) + ix;
227	        int indx2 = n_cells_[0] * n_cells_[1] * iz + n_cells_[0] * iy + ix;
228	        universes_[indx1] = std::stoi(univ_words[indx2]);
229	      }
230	    }
231	  }
232	}
