286	//==============================================================================
287	
288	void RectLattice::get_indices(
289	  Position r, Direction u, array<int, 3>& result) const
290	{
291	  // Determine x index, accounting for coincidence
292	  double ix_ {(r.x - lower_left_.x) / pitch_.x};
293	  long ix_close {std::lround(ix_)};
294	  if (coincident(ix_, ix_close)) {
295	    result[0] = (u.x > 0) ? ix_close : ix_close - 1;
296	  } else {
297	    result[0] = std::floor(ix_);
298	  }
299	
300	  // Determine y index, accounting for coincidence
301	  double iy_ {(r.y - lower_left_.y) / pitch_.y};
302	  long iy_close {std::lround(iy_)};
303	  if (coincident(iy_, iy_close)) {
304	    result[1] = (u.y > 0) ? iy_close : iy_close - 1;
305	  } else {
306	    result[1] = std::floor(iy_);
307	  }
308	
309	  // Determine z index, accounting for coincidence
310	  result[2] = 0;
311	  if (is_3d_) {
312	    double iz_ {(r.z - lower_left_.z) / pitch_.z};
313	    long iz_close {std::lround(iz_)};
314	    if (coincident(iz_, iz_close)) {
315	      result[2] = (u.z > 0) ? iz_close : iz_close - 1;
316	    } else {
317	      result[2] = std::floor(iz_);
318	    }
319	  }
320	}
