322	int RectLattice::get_flat_index(const array<int, 3>& i_xyz) const
323	{
324	  return n_cells_[0] * n_cells_[1] * i_xyz[2] + n_cells_[0] * i_xyz[1] +
325	         i_xyz[0];
326	}
