543	//==============================================================================
544	
545	vector<int32_t>::iterator CSGCell::find_left_parenthesis(
546	  vector<int32_t>::iterator start, const vector<int32_t>& infix)
547	{
548	  // start search at zero
549	  int parenthesis_level = 0;
550	  auto it = start;
551	  while (it != infix.begin()) {
552	    // look at two tokens at a time
553	    int32_t one = *it;
554	    int32_t two = *(it - 1);
555	
556	    // decrement parenthesis level if there are two adjacent surfaces
557	    if (one < OP_UNION && two < OP_UNION) {
558	      parenthesis_level--;
559	      // increment if there are two adjacent operators
560	    } else if (one >= OP_UNION && two >= OP_UNION) {
561	      parenthesis_level++;
562	    }
563	
564	    // if the level gets to zero, return the position
565	    if (parenthesis_level == 0) {
566	      // move the iterator back one before leaving the loop
567	      // so that all tokens in the parenthesis block are included
568	      it--;
569	      break;
570	    }
571	
572	    // continue loop, one token at a time
573	    it--;
574	  }
575	  return it;
576	}
