710	//==============================================================================
711	
712	void Region::apply_demorgan(
713	  vector<int32_t>::iterator start, vector<int32_t>::iterator stop)
714	{
715	  do {
716	    if (*start < OP_UNION) {
717	      *start *= -1;
718	    } else if (*start == OP_UNION) {
719	      *start = OP_INTERSECTION;
720	    } else if (*start == OP_INTERSECTION) {
721	      *start = OP_UNION;
722	    }
723	    start++;
724	  } while (start < stop);
725	}
