31	void read_geometry_xml()
32	{
33	  // Display output message
34	  write_message("Reading geometry XML file...", 5);
35	
36	  // Check if geometry.xml exists
37	  std::string filename = settings::path_input + "geometry.xml";
38	  if (!file_exists(filename)) {
39	    fatal_error("Geometry XML file '" + filename + "' does not exist!");
40	  }
41	
42	  // Parse settings.xml file
43	  pugi::xml_document doc;
44	  auto result = doc.load_file(filename.c_str());
45	  if (!result) {
46	    fatal_error("Error processing geometry.xml file.");
47	  }
48	
49	  // Get root element
50	  pugi::xml_node root = doc.document_element();
51	
52	  read_geometry_xml(root);
