55	void read_geometry_xml(pugi::xml_node root)
56	{
57	  // Read surfaces, cells, lattice
58	  std::set<std::pair<int, int>> periodic_pairs;
59	  std::unordered_map<int, double> albedo_map;
60	  std::unordered_map<int, int> periodic_sense_map;
61	
62	  read_surfaces(root, periodic_pairs, albedo_map, periodic_sense_map);
63	  read_cells(root);
64	  prepare_boundary_conditions(periodic_pairs, albedo_map, periodic_sense_map);
65	  read_lattices(root);
66	
67	  // Check to make sure a boundary condition was applied to at least one
68	  // surface
69	  bool boundary_exists = false;
70	  for (const auto& surf : model::surfaces) {
71	    if (surf->bc_) {
72	      boundary_exists = true;
73	      break;
74	    }
75	  }
76	
77	  if (settings::run_mode != RunMode::PLOTTING &&
78	      settings::run_mode != RunMode::VOLUME && !boundary_exists) {
79	    fatal_error("No boundary conditions were applied to any surfaces!");
80	  }
81	
82	  // Allocate universes, universe cell arrays, and assign base universe
83	  model::root_universe = find_root_universe();
84	
85	  // if the root universe is DAGMC geometry, make sure the model is well-formed
86	  check_dagmc_root_univ();
87	}
