179	void assign_temperatures()
180	{
181	  for (auto& c : model::cells) {
182	    // Ignore non-material cells and cells with defined temperature.
183	    if (c->material_.size() == 0)
184	      continue;
185	    if (c->sqrtkT_.size() > 0)
186	      continue;
187	
188	    c->sqrtkT_.reserve(c->material_.size());
189	    for (auto i_mat : c->material_) {
190	      if (i_mat == MATERIAL_VOID) {
191	        // Set void region to 0K.
192	        c->sqrtkT_.push_back(0);
193	      } else {
194	        const auto& mat {model::materials[i_mat]};
195	        c->sqrtkT_.push_back(std::sqrt(K_BOLTZMANN * mat->temperature()));
196	      }
197	    }
198	  }
199	}
