220	
221	void get_temperatures(
222	  vector<vector<double>>& nuc_temps, vector<vector<double>>& thermal_temps)
223	{
224	  for (const auto& cell : model::cells) {
225	    // Skip non-material cells.
226	    if (cell->fill_ != C_NONE)
227	      continue;
228	
229	    for (int j = 0; j < cell->material_.size(); ++j) {
230	      // Skip void materials
231	      int i_material = cell->material_[j];
232	      if (i_material == MATERIAL_VOID)
233	        continue;
234	
235	      // Get temperature(s) of cell (rounding to nearest integer)
236	      vector<double> cell_temps;
237	      if (cell->sqrtkT_.size() == 1) {
238	        double sqrtkT = cell->sqrtkT_[0];
239	        cell_temps.push_back(sqrtkT * sqrtkT / K_BOLTZMANN);
240	      } else if (cell->sqrtkT_.size() == cell->material_.size()) {
241	        double sqrtkT = cell->sqrtkT_[j];
242	        cell_temps.push_back(sqrtkT * sqrtkT / K_BOLTZMANN);
243	      } else {
244	        for (double sqrtkT : cell->sqrtkT_)
245	          cell_temps.push_back(sqrtkT * sqrtkT / K_BOLTZMANN);
246	      }
247	
248	      const auto& mat {model::materials[i_material]};
249	      for (const auto& i_nuc : mat->nuclide_) {
250	        for (double temperature : cell_temps) {
251	          // Add temperature if it hasn't already been added
252	          if (!contains(nuc_temps[i_nuc], temperature))
253	            nuc_temps[i_nuc].push_back(temperature);
254	        }
255	      }
256	
257	      for (const auto& table : mat->thermal_tables_) {
258	        // Get index in data::thermal_scatt array
259	        int i_sab = table.index_table;
260	
261	        for (double temperature : cell_temps) {
262	          // Add temperature if it hasn't already been added
263	          if (!contains(thermal_temps[i_sab], temperature))
264	            thermal_temps[i_sab].push_back(temperature);
265	        }
266	      }
267	    }
268	  }
269	}
