288	
289	int32_t find_root_universe()
290	{
291	  // Find all the universes listed as a cell fill.
292	  std::unordered_set<int32_t> fill_univ_ids;
293	  for (const auto& c : model::cells) {
294	    fill_univ_ids.insert(c->fill_);
295	  }
296	
297	  // Find all the universes contained in a lattice.
298	  for (const auto& lat : model::lattices) {
299	    for (auto it = lat->begin(); it != lat->end(); ++it) {
300	      fill_univ_ids.insert(*it);
301	    }
302	    if (lat->outer_ != NO_OUTER_UNIVERSE) {
303	      fill_univ_ids.insert(lat->outer_);
304	    }
305	  }
306	
307	  // Figure out which universe is not in the set.  This is the root universe.
308	  bool root_found {false};
309	  int32_t root_univ;
310	  for (int32_t i = 0; i < model::universes.size(); i++) {
311	    auto search = fill_univ_ids.find(model::universes[i]->id_);
312	    if (search == fill_univ_ids.end()) {
313	      if (root_found) {
314	        fatal_error("Two or more universes are not used as fill universes, so "
315	                    "it is not possible to distinguish which one is the root "
316	                    "universe.");
317	      } else {
318	        root_found = true;
319	        root_univ = i;
320	      }
321	    }
322	  }
323	  if (!root_found)
324	    fatal_error("Could not find a root universe.  Make sure "
325	                "there are no circular dependencies in the geometry.");
326	
327	  return root_univ;
328	}
