507	
508	std::string distribcell_path_inner(int32_t target_cell, int32_t map,
509	  int32_t target_offset, const Universe& search_univ, int32_t offset)
510	{
511	  std::stringstream path;
512	
513	  path << "u" << search_univ.id_ << "->";
514	
515	  // Check to see if this universe directly contains the target cell.  If so,
516	  // write to the path and return.
517	  for (int32_t cell_indx : search_univ.cells_) {
518	    if ((cell_indx == target_cell) && (offset == target_offset)) {
519	      Cell& c = *model::cells[cell_indx];
520	      path << "c" << c.id_;
521	      return path.str();
522	    }
523	  }
524	
525	  // The target must be further down the geometry tree and contained in a fill
526	  // cell or lattice cell in this universe.  Find which cell contains the
527	  // target.
528	  vector<std::int32_t>::const_reverse_iterator cell_it {
529	    search_univ.cells_.crbegin()};
530	  for (; cell_it != search_univ.cells_.crend(); ++cell_it) {
531	    Cell& c = *model::cells[*cell_it];
532	
533	    // Material cells don't contain other cells so ignore them.
534	    if (c.type_ != Fill::MATERIAL) {
535	      int32_t temp_offset = offset + c.offset_[map];
536	      if (c.type_ == Fill::LATTICE) {
537	        Lattice& lat = *model::lattices[c.fill_];
538	        int32_t indx = lat.universes_.size() * map + lat.begin().indx_;
539	        temp_offset += lat.offsets_[indx];
540	      }
541	
542	      // The desired cell is the first cell that gives an offset smaller or
543	      // equal to the target offset.
544	      if (temp_offset <= target_offset)
545	        break;
546	    }
547	  }
548	
549	  // if we get through the loop without finding an appropriate entry, throw
550	  // an error
551	  if (cell_it == search_univ.cells_.crend()) {
552	    fatal_error(
553	      fmt::format("Failed to generate a text label for distribcell with ID {}."
554	                  "The current label is: '{}'",
555	        model::cells[target_cell]->id_, path.str()));
556	  }
557	
558	  // Add the cell to the path string.
559	  Cell& c = *model::cells[*cell_it];
560	  path << "c" << c.id_ << "->";
561	
562	  if (c.type_ == Fill::UNIVERSE) {
563	    // Recurse into the fill cell.
564	    offset += c.offset_[map];
565	    path << distribcell_path_inner(
566	      target_cell, map, target_offset, *model::universes[c.fill_], offset);
567	    return path.str();
568	  } else {
569	    // Recurse into the lattice cell.
570	    Lattice& lat = *model::lattices[c.fill_];
571	    path << "l" << lat.id_;
572	    for (ReverseLatticeIter it = lat.rbegin(); it != lat.rend(); ++it) {
573	      int32_t indx = lat.universes_.size() * map + it.indx_;
574	      int32_t temp_offset = offset + lat.offsets_[indx] + c.offset_[map];
575	      if (temp_offset <= target_offset) {
576	        offset = temp_offset;
577	        path << "(" << lat.index_to_string(it.indx_) << ")->";
578	        path << distribcell_path_inner(
579	          target_cell, map, target_offset, *model::universes[*it], offset);
580	        return path.str();
581	      }
582	    }
583	    throw std::runtime_error {"Error determining distribcell path."};
584	  }
585	}
586	
587	std::string distribcell_path(
588	  int32_t target_cell, int32_t map, int32_t target_offset)
589	{
590	  auto& root_univ = *model::universes[model::root_universe];
591	  return distribcell_path_inner(target_cell, map, target_offset, root_univ, 0);
592	}
