347	vector<int32_t> parse_cell_material_xml(pugi::xml_node node, int32_t cell_id)
348	{
349	  vector<std::string> mats {
350	    get_node_array<std::string>(node, "material", true)};
351	  if (mats.empty()) {
352	    fatal_error(fmt::format(
353	      "An empty material element was specified for cell {}", cell_id));
354	  }
355	  vector<int32_t> material;
356	  material.reserve(mats.size());
357	  for (const auto& mat : mats) {
358	    if (mat == "void") {
359	      material.push_back(MATERIAL_VOID);
360	    } else {
361	      material.push_back(std::stoi(mat));
362	    }
363	  }
364	  return material;
