370	  if (temperatures.empty()) {
371	    fatal_error(fmt::format(
372	      "An empty temperature element was specified for cell {}", cell_id));
373	  }
374	  for (auto T : temperatures) {
375	    if (T < 0) {
376	      fatal_error(fmt::format(
377	        "Cell {} was specified with a negative temperature", cell_id));
