401	// CSGCell implementation
402	//==============================================================================
403	
404	CSGCell::CSGCell(pugi::xml_node cell_node)
405	{
406	  if (check_for_node(cell_node, "id")) {
407	    id_ = std::stoi(get_node_value(cell_node, "id"));
408	  } else {
409	    fatal_error("Must specify id of cell in geometry XML file.");
410	  }
411	
412	  if (check_for_node(cell_node, "name")) {
413	    name_ = get_node_value(cell_node, "name");
414	  }
415	
416	  if (check_for_node(cell_node, "universe")) {
417	    universe_ = std::stoi(get_node_value(cell_node, "universe"));
418	  } else {
419	    universe_ = 0;
420	  }
421	
422	  // Make sure that either material or fill was specified, but not both.
423	  bool fill_present = check_for_node(cell_node, "fill");
424	  bool material_present = check_for_node(cell_node, "material");
425	  if (!(fill_present || material_present)) {
426	    fatal_error(
427	      fmt::format("Neither material nor fill was specified for cell {}", id_));
428	  }
429	  if (fill_present && material_present) {
430	    fatal_error(fmt::format("Cell {} has both a material and a fill specified; "
431	                            "only one can be specified per cell",
432	      id_));
433	  }
434	
435	  if (fill_present) {
436	    fill_ = std::stoi(get_node_value(cell_node, "fill"));
437	    if (fill_ == universe_) {
438	      fatal_error(fmt::format("Cell {} is filled with the same universe that "
439	                              "it is contained in.",
440	        id_));
441	    }
442	  } else {
443	    fill_ = C_NONE;
444	  }
445	
446	  // Read the material element.  There can be zero materials (filled with a
447	  // universe), more than one material (distribmats), and some materials may
448	  // be "void".
449	  if (material_present) {
450	    material_ = parse_cell_material_xml(cell_node, id_);
451	  }
452	
453	  // Read the temperature element which may be distributed like materials.
454	  if (check_for_node(cell_node, "temperature")) {
455	    sqrtkT_ = parse_cell_temperature_xml(cell_node, id_);
456	    sqrtkT_.shrink_to_fit();
457	
458	    // Make sure this is a material-filled cell.
459	    if (material_.size() == 0) {
460	      fatal_error(fmt::format(
461	        "Cell {} was specified with a temperature but no material. Temperature"
462	        "specification is only valid for cells filled with a material.",
463	        id_));
464	    }
465	
466	    // Convert to sqrt(k*T).
467	    for (auto& T : sqrtkT_) {
468	      T = std::sqrt(K_BOLTZMANN * T);
469	    }
470	  }
471	
472	  // Read the density element which can be distributed similar to temperature.
473	  // These get assigned to the density multiplier, requiring a division by
474	  // the material density.
475	  // Note: calculating the actual density multiplier is deferred until materials
476	  // are finalized. density_mult_ contains the true density in the meantime.
477	  if (check_for_node(cell_node, "density")) {
478	    density_mult_ = parse_cell_density_xml(cell_node, id_);
479	    density_mult_.shrink_to_fit();
480	
481	    // Make sure this is a material-filled cell.
482	    if (material_.size() == 0) {
483	      fatal_error(fmt::format(
484	        "Cell {} was specified with a density but no material. Density"
485	        "specification is only valid for cells filled with a material.",
486	        id_));
487	    }
488	
489	    // Make sure this is a non-void material.
490	    for (auto mat_id : material_) {
491	      if (mat_id == MATERIAL_VOID) {
492	        fatal_error(fmt::format(
493	          "Cell {} was specified with a density, but contains a void "
494	          "material. Density specification is only valid for cells "
495	          "filled with a non-void material.",
496	          id_));
497	      }
498	    }
499	  }
500	
501	  // Read the region specification.
502	  std::string region_spec;
503	  if (check_for_node(cell_node, "region")) {
504	    region_spec = get_node_value(cell_node, "region");
505	  }
506	
507	  // Get a tokenized representation of the region specification and apply De
508	  // Morgans law
509	  Region region(region_spec, id_);
510	  region_ = region;
511	
512	  // Read the translation vector.
513	  if (check_for_node(cell_node, "translation")) {
514	    if (fill_ == C_NONE) {
515	      fatal_error(fmt::format("Cannot apply a translation to cell {}"
516	                              " because it is not filled with another universe",
517	        id_));
518	    }
519	
520	    auto xyz {get_node_array<double>(cell_node, "translation")};
521	    if (xyz.size() != 3) {
522	      fatal_error(
523	        fmt::format("Non-3D translation vector applied to cell {}", id_));
524	    }
525	    translation_ = xyz;
526	  }
527	
528	  // Read the rotation transform.
529	  if (check_for_node(cell_node, "rotation")) {
530	    auto rot {get_node_array<double>(cell_node, "rotation")};
531	    set_rotation(rot);
532	  }
533	}
