535	//==============================================================================
536	
537	void CSGCell::to_hdf5_inner(hid_t group_id) const
538	{
539	  write_string(group_id, "geom_type", "csg", false);

850	  vector<int32_t> stack;
851	
852	  for (int32_t token : expression_) {
853	    if (token < OP_UNION) {
854	      // If token is not an operator, add it to output
855	      rpn.push_back(token);
856	    } else if (token < OP_RIGHT_PAREN) {
857	      // Regular operators union, intersection, complement
858	      while (stack.size() > 0) {
859	        int32_t op = stack.back();
860	
861	        if (op < OP_RIGHT_PAREN && ((token == OP_COMPLEMENT && token < op) ||
862	                                     (token != OP_COMPLEMENT && token <= op))) {
863	          // While there is an operator, op, on top of the stack, if the token
864	          // is left-associative and its precedence is less than or equal to
865	          // that of op or if the token is right-associative and its precedence
866	          // is less than that of op, move op to the output queue and push the
867	          // token on to the stack. Note that only complement is
868	          // right-associative.
869	          rpn.push_back(op);
870	          stack.pop_back();
871	        } else {
872	          break;
873	        }
874	      }
875	
876	      stack.push_back(token);
877	
878	    } else if (token == OP_LEFT_PAREN) {
879	      // If the token is a left parenthesis, push it onto the stack
880	      stack.push_back(token);
881	
882	    } else {
883	      // If the token is a right parenthesis, move operators from the stack to
884	      // the output queue until reaching the left parenthesis.
885	      for (auto it = stack.rbegin(); *it != OP_LEFT_PAREN; it++) {
886	        // If we run out of operators without finding a left parenthesis, it
887	        // means there are mismatched parentheses.
888	        if (it == stack.rend()) {
889	          fatal_error(fmt::format(
890	            "Mismatched parentheses in region specification for cell {}",
891	            cell_id));
892	        }
893	        rpn.push_back(stack.back());
894	        stack.pop_back();
895	      }
896	
897	      // Pop the left parenthesis.
898	      stack.pop_back();
899	    }
900	  }
901	
902	  while (stack.size() > 0) {
903	    int32_t op = stack.back();
904	
905	    // If the operator is a parenthesis it is mismatched.
906	    if (op >= OP_RIGHT_PAREN) {
907	      fatal_error(fmt::format(
908	        "Mismatched parentheses in region specification for cell {}", cell_id));
909	    }
910	
911	    rpn.push_back(stack.back());
912	    stack.pop_back();
913	  }
914	
915	  return rpn;
916	}
