1080	
1081	BoundingBox Region::bounding_box_simple() const
1082	{
1083	  BoundingBox bbox;
1084	  for (int32_t token : expression_) {
1085	    bbox &= model::surfaces[abs(token) - 1]->bounding_box(token > 0);
