1090	//==============================================================================
1091	
1092	BoundingBox Region::bounding_box_complex(vector<int32_t> postfix) const
1093	{
1094	  vector<BoundingBox> stack(postfix.size());
1095	  int i_stack = -1;
1096	
1097	  for (auto& token : postfix) {
1098	    if (token == OP_UNION) {
1099	      stack[i_stack - 1] = stack[i_stack - 1] | stack[i_stack];
1100	      i_stack--;
1101	    } else if (token == OP_INTERSECTION) {
1102	      stack[i_stack - 1] = stack[i_stack - 1] & stack[i_stack];
1103	      i_stack--;
1104	    } else {
1105	      i_stack++;
1106	      stack[i_stack] = model::surfaces[abs(token) - 1]->bounding_box(token > 0);
1107	    }
1108	  }
1109	
1110	  assert(i_stack == 0);
1111	  return stack.front();
1112	}
