1115	
1116	vector<int32_t> Region::surfaces() const
1117	{
1118	  if (simple_) {
1119	    return expression_;
1120	  }
1121	
1122	  vector<int32_t> surfaces = expression_;
1123	
1124	  auto it = std::find_if(surfaces.begin(), surfaces.end(),
1125	    [&](const auto& value) { return value >= OP_UNION; });
1126	
1127	  while (it != surfaces.end()) {
1128	    surfaces.erase(it);
1129	
1130	    it = std::find_if(surfaces.begin(), surfaces.end(),
1131	      [&](const auto& value) { return value >= OP_UNION; });
1132	  }
1133	
1134	  return surfaces;
1135	}
