1138	// Non-method functions
1139	//==============================================================================
1140	
1141	void read_cells(pugi::xml_node node)
1142	{
1143	  // Count the number of cells.
1144	  int n_cells = 0;
1145	  for (pugi::xml_node cell_node : node.children("cell")) {
1146	    n_cells++;
1147	  }
1148	
1149	  // Loop over XML cell elements and populate the array.
1150	  model::cells.reserve(n_cells);
1151	  for (pugi::xml_node cell_node : node.children("cell")) {
1152	    model::cells.push_back(make_unique<CSGCell>(cell_node));
1153	  }
1154	
1155	  // Fill the cell map.
1156	  for (int i = 0; i < model::cells.size(); i++) {
1157	    int32_t id = model::cells[i]->id_;
1158	    auto search = model::cell_map.find(id);
1159	    if (search == model::cell_map.end()) {
1160	      model::cell_map[id] = i;
1161	    } else {
1162	      fatal_error(
